"""Compatibility ports for the earlier lifecycle doubles, not Android layout proof.
The independent Android 16 suite owns real StaticLayout, spans, measurement and pixels.
No production layout policy or adapter is replaced here.
"""
def apply(files, formatter=False):
    files.setdefault('android/graphics/Rect.java','''package android.graphics;public class Rect{public int left,top,right,bottom;public Rect(){}public Rect(int l,int t,int r,int b){left=l;top=t;right=r;bottom=b;}public Rect(Rect r){this(r.left,r.top,r.right,r.bottom);}public boolean isEmpty(){return left>=right||top>=bottom;}public void setEmpty(){left=top=right=bottom=0;}public boolean intersect(Rect r){int l=Math.max(left,r.left),t=Math.max(top,r.top),rr=Math.min(right,r.right),b=Math.min(bottom,r.bottom);if(l>=rr||t>=b)return false;left=l;top=t;right=rr;bottom=b;return true;}public boolean equals(Object o){if(!(o instanceof Rect))return false;Rect r=(Rect)o;return left==r.left&&top==r.top&&right==r.right&&bottom==r.bottom;}}''')
    files.update({
        'android/text/method/TransformationMethod.java':'package android.text.method;public interface TransformationMethod{}',
        'android/text/TextPaint.java':'package android.text;public class TextPaint extends android.graphics.Paint{public void set(android.graphics.Paint p){size=p.size;}public void setTextSize(float v){size=v;}}',
        'android/text/SpannableStringBuilder.java':'''package android.text;public class SpannableStringBuilder implements CharSequence{final StringBuilder value=new StringBuilder();public SpannableStringBuilder(CharSequence s){value.append(s);}public SpannableStringBuilder append(CharSequence s){value.append(s);return this;}public SpannableStringBuilder replace(int a,int b,String s){value.replace(a,b,s);return this;}public SpannableStringBuilder insert(int i,String s){value.insert(i,s);return this;}public SpannableStringBuilder delete(int a,int b){value.delete(a,b);return this;}public void setSpan(Object o,int a,int b,int flags){}public int length(){return value.length();}public char charAt(int i){return value.charAt(i);}public CharSequence subSequence(int a,int b){return value.subSequence(a,b);}public String toString(){return value.toString();}}''',
        'android/text/Layout.java':'''package android.text;public class Layout{public enum Alignment{ALIGN_NORMAL}public static final int BREAK_STRATEGY_SIMPLE=0;public static float getDesiredWidth(CharSequence text,TextPaint paint){float width=0;for(String line:text.toString().split("\\n",-1))width=Math.max(width,paint.measureText(line));return width;}}''',
        'android/text/StaticLayout.java':'''package android.text;public class StaticLayout extends Layout{float[] widths;int height;StaticLayout(CharSequence t,TextPaint p,int w){java.util.List<Float> lines=new java.util.ArrayList<>();for(String line:t.toString().split("\\n",-1)){float length=p.measureText(line);int count=Math.max(1,(int)Math.ceil(length/Math.max(1,w)));for(int i=0;i<count;i++)lines.add(Math.min(w,Math.max(0,length-i*w)));}widths=new float[lines.size()];for(int i=0;i<widths.length;i++)widths[i]=lines.get(i);height=(int)Math.ceil(widths.length*p.size);}public int getLineCount(){return widths.length;}public float getLineWidth(int i){return widths[i];}public int getHeight(){return height;}public static class Builder{CharSequence t;TextPaint p;int w;Builder(CharSequence t,TextPaint p,int w){this.t=t;this.p=p;this.w=w;}public static Builder obtain(CharSequence t,int a,int b,TextPaint p,int w){return new Builder(t.subSequence(a,b),p,w);}public Builder setAlignment(Alignment a){return this;}public Builder setIncludePad(boolean b){return this;}public Builder setLineSpacing(float a,float b){return this;}public Builder setBreakStrategy(int b){return this;}public StaticLayout build(){return new StaticLayout(t,p,w);}}}''',
        'android/widget/LinearLayout.java':'package android.widget;public class LinearLayout extends android.view.ViewGroup{public static final int HORIZONTAL=0;public int getOrientation(){return 0;}}',
    })
    paint=files['android/graphics/Paint.java']
    if 'getFontMetricsInt()' not in paint:paint=paint.replace('public float measureText','public static class FontMetricsInt{public int top,bottom;}public FontMetricsInt getFontMetricsInt(){FontMetricsInt f=new FontMetricsInt();f.top=-(int)Math.ceil(size);return f;}public float measureText')
    files['android/graphics/Paint.java']=paint
    view=files['android/view/View.java']
    if 'getTag()' not in view:view=view.replace('public static final int VISIBLE', 'public Object tag;public Object getTag(){return tag;}public void setTag(Object v){tag=v;}public static final int VISIBLE')
    if 'getLayoutDirection()' not in view:view=view.replace('public static final int VISIBLE', 'public static final int LAYOUT_DIRECTION_RTL=1;public int getLayoutDirection(){return '+('rtl?1:0' if 'boolean attached=true,clickable,rtl' in view else '0')+';}public static final int VISIBLE')
    if 'isLayoutRequested()' not in view:view=view.replace('public void invalidate()', 'public boolean isLayoutRequested(){return false;}public void invalidate()')
    if 'getWindowVisibility()' not in view:view=view.replace('public void invalidate()', 'public int getWindowVisibility(){return VISIBLE;}public void invalidate()')
    if formatter and 'getContentDescription()' not in view:
        view=view.replace('public void setContentDescription(CharSequence s){}','public CharSequence description;public void setContentDescription(CharSequence s){description=s;}public CharSequence getContentDescription(){return description;}')
    if 'getClipBounds()' not in view:view=view.replace('public void invalidate()', 'public android.graphics.Rect clip;public android.graphics.Rect getClipBounds(){return clip;}public void setClipBounds(android.graphics.Rect value){clip=value;}public void invalidate()')
    if 'getGlobalVisibleRect(' not in view:view=view.replace('public void invalidate()', 'public boolean getGlobalVisibleRect(android.graphics.Rect rect){int[] xy=new int[2];getLocationOnScreen(xy);rect.left=xy[0];rect.top=xy[1];rect.right=xy[0]+getWidth();rect.bottom=xy[1]+getHeight();return isShown()&&!rect.isEmpty();}public void invalidate()')
    if 'getScaleX()' not in view:view=view.replace('public void invalidate()', 'public float getScaleX(){return 1;}public float getScaleY(){return 1;}public void invalidate()')
    if 'getLocationInWindow(' not in view:view=view.replace('public void invalidate()', 'public void getLocationInWindow(int[] location){getLocationOnScreen(location);}public void invalidate()')
    if 'removeOnAttachStateChangeListener(' not in view:view=view.replace('public void invalidate()', 'public void removeOnAttachStateChangeListener(OnAttachStateChangeListener listener){}public void invalidate()')
    files['android/view/View.java']=view
    if formatter and 'static boolean equals(' not in files['android/text/TextUtils.java']:
        files['android/text/TextUtils.java']=files['android/text/TextUtils.java'].replace('public class TextUtils{','public class TextUtils{public static boolean equals(CharSequence a,CharSequence b){return a==b||a!=null&&b!=null&&a.toString().contentEquals(b);}')
    text=files['android/widget/TextView.java'].replace('android.graphics.Paint paint=new android.graphics.Paint()', 'android.text.TextPaint paint=new android.text.TextPaint()').replace('android.graphics.Paint getPaint()', 'android.text.TextPaint getPaint()')
    if 'getMaxWidth()' not in text:text=text.replace('public float getTextSize()', 'public int maxWidth=Integer.MAX_VALUE;public int getMaxWidth(){return maxWidth;}public void setMaxWidth(int v){maxWidth=v;}public float getTextSize()')
    if 'isSingleLine()' not in text:text=text.replace('public float getTextSize()', '''public boolean singleLine=true,horizontal=true;public int maxLines=1;public android.text.method.TransformationMethod transform;public boolean isSingleLine(){return singleLine;}public boolean isHorizontallyScrollable(){return horizontal;}public void setSingleLine(boolean v){singleLine=v;}public void setHorizontallyScrolling(boolean v){horizontal=v;}public int getMaxLines(){return maxLines;}public void setMaxLines(int v){maxLines=v;}public android.text.method.TransformationMethod getTransformationMethod(){return transform;}public void setTransformationMethod(android.text.method.TransformationMethod v){transform=v;}public boolean getIncludeFontPadding(){return true;}public float getLineSpacingExtra(){return 0;}public float getLineSpacingMultiplier(){return 1;}public int length(){return text.length();}public float getTextSize()''')
    if 'void setText(' not in text:text=text.replace('public float getTextSize()', 'public void setText(CharSequence v){text=v.toString();}public float getTextSize()')
    files['android/widget/TextView.java']=text
    key='ls/augment/com/hook/ControlCenterHeaderHook.java'
    if formatter:files.pop(key,None)
    else:files[key]='package ls.augment.com.hook;final class ControlCenterHeaderHook{static void spaceBlocked(android.widget.TextView v,boolean b){}static boolean renderClock(android.widget.TextView v){return false;}}'
